test "kanji_table properties" {
    try std.testing.expectEqual(@as(usize, ENTRY_COUNT), unicode_to_qr_kanji.len);
    try std.testing.expectEqual(@as(usize, 27516), @sizeOf(@TypeOf(unicode_to_qr_kanji)));
    var prev_cp: u21 = 0;
    for (unicode_to_qr_kanji, 0..) |entry, i| {
        const cp = getUnicode(entry);
        const qr = getQrKanji(entry);
        try std.testing.expect(qr < 8192);
        if (i > 0) {
            try std.testing.expect(cp > prev_cp);
        }
        try std.testing.expectEqual(entry, pack(cp, qr));
        prev_cp = cp;
    }
}
